import networkx as nx

def count_independent_sets(G):
    memo = {}
    def solve(nodes):
        if not nodes:
            return 1
        state = tuple(sorted(nodes))
        if state in memo:
            return memo[state]

        v = min(nodes, key=lambda x: len([n for n in G.neighbors(x) if n in nodes]))

        res = solve(nodes - {v})
        neighbors = set(G.neighbors(v))
        res += solve(nodes - {v} - neighbors)

        memo[state] = res
        return res

G = nx.Graph()
G.add_nodes_from(range(1, 43))
for i in range(1, 42):
    G.add_edge(i, i+1)
for i in range(1, 22):
    G.add_edge(i, i+21)

print(count_independent_sets(set(range(1, 43))))

